INSERT INTO articles(id,slug,title,subtitle,body,category,region,kind,image,image_credit,author,locale,status,featured,demo,sponsored,publish_at,created_at,updated_at,sources,tags) VALUES ('geovyora-wilson-isidor-2026','wilson-isidor-deklarasyon-ayiti-repiblik-dominikenn','Wilson Isidor: yon doub ki fè Ayiti pale, yon pawòl ki mete de peyi an diskisyon','Apre viktwa 4–1 Grenadye yo nan Santo Domingo, atakan ayisyen an te selebre ak yon fraz ki pran dife sou rezo yo.','Nan dat 1ye oktòb, Ayiti bat Repiblik Dominikèn 4–1 nan Santo Domingo nan Lig Nasyon Concacaf la. Wilson Isidor make de nan gòl yo. Men se pa sèlman pèfòmans li sou teren an ki fè non li tounen gwo sijè: yon fraz li rele apre match la vin tounen sant yon diskisyon sou fyète, rivalite ak sans pawòl yo.

## Yon match ki te vire nan dezyèm mitan an

Ayiti te pran devan depi nevyèm minit la sou gòl Don Deedson Louicius. Isidor te rate yon penalite nan 21yèm minit la, dapre Le Nouvelliste. Nan dezyèm mitan an, li reprann tèt li: li mete gòl nan 51yèm minit la, epi li fè 3–1 nan 67yèm lan. Dorny Romero te make pou ekip dominiken an ant de gòl sa yo. Yassin Fortuné te fè dènye gòl Ayiti a nan 77yèm minit la.

Se premye doub Isidor pou seleksyon ayisyen an, dapre jounal la. Rezilta a te bay Ayiti yon viktwa enpòtan nan gwoup la epi ede ekip la jwenn plas nan kar de final Lig Nasyon an.

## Pawòl la apre siflèt la

Apre match la, Isidor te rele: “L’Hispaniola c’est Haïti! This is Haiti!” Pawòl la gaye rapid. Ispanyola se zile kote Ayiti ak Repiblik Dominikèn chita ansanm. Se poutèt sa fraz la te ka tande tankou yon deklarasyon sou idantite, men anpil moun te pran li kòm yon pwovokasyon sou teritwa.

Federasyon Ayisyèn Foutbòl la te defann selebrasyon an kòm yon ekspresyon atachman ak rasin ayisyen Isidor, epi li te di sa pa dwe konsidere kòm ostilite oswa mank respè pou yon lòt pèp. Sa se pozisyon federasyon an. Pawòl la, poukont li, pa chanje reyalite jewografik la: zile a pataje ant de peyi.

## Repons yo ak limit sa nou konnen

Associated Press rapòte Federasyon Foutbòl Dominikèn nan te depoze yon plent devan Concacaf, epi òganizasyon an te louvri yon dosye disiplinè. Men, menm rapò AP a fè konnen minis espò dominiken an pa t site Isidor lè li te anonse ekip ayisyen an pa t ap gen dwa jwe nan estad peyi a ankò, li te pale pito sou domaj fanatik yo ta lakòz nan estad la. Rapò AP ki te parèt 5 oktòb la pa bay yon desizyon final sou dosye a.

Se konsa yon gwo moman foutbòl vin tounen yon deba ki mande plis pase yon reyaksyon rapid sou entènèt. Isidor te make de gòl nan yon viktwa ki pote pwa espòtif pou Ayiti. FHF a prezante rèl la kòm selebrasyon. Diskisyon ki vin apre a montre jan rivalite ant vwazen yo ka fè yon fraz pran sans politik, sitou lè memwa ak relasyon ant de peyi yo deja chaje.','Espò','haiti','article','/static/articles/wilson-isidor-2026.jpg','Timmy96 / Wikimedia Commons — CC0 1.0 (foto a pa modifye)','Geovyora','ht','published','0','0','0','2026-10-10T00:00:00+00:00','2026-10-10T00:00:00+00:00','2026-10-10T00:00:00+00:00','https://www.concacaf.com/competitions/nations-league/news/bacuna-seals-curacao-s-third-straight-win
https://www.concacaf.com/competitions/nations-league/news/haiti-and-curacao-advance-to-nations-league-quarterfinals
https://apnews.com/article/34ee8ca588f6e54b33f6f2723b3a510c
https://lenouvelliste.com/en/article/272541/wilson-isidor-scores-his-first-brace-for-haiti
https://lenouvelliste.com/en/article/272591/the-celebration-of-wilson-isidor-was-strictly-sporting-according-to-the-haitian-football-federation
https://commons.wikimedia.org/wiki/File:Wilson_Isidor_05092026_(3).jpg
https://creativecommons.org/publicdomain/zero/1.0/','Wilson Isidor,Ayiti,Repiblik Dominikèn,Nations League,Foutbòl') ON CONFLICT(slug) DO NOTHING;
INSERT INTO translations(id,target_type,target_id,version,locale,data,manual,created_at) SELECT 'geovyora-wilson-isidor-2026-fr','article','geovyora-wilson-isidor-2026','2026-10-10T00:00:00+00:00','fr','{"title":"Wilson Isidor : un doublé pour Haïti, une phrase qui divise","subtitle":"Après la victoire 4-1 des Grenadiers à Saint-Domingue, l’attaquant a célébré avec des mots devenus le sujet d’une controverse.","body":"Le 1er octobre, Haïti a battu la République dominicaine 4-1 à Saint-Domingue en Ligue des nations de la Concacaf. Wilson Isidor a inscrit deux buts. Mais sa performance n’est pas la seule raison pour laquelle son nom a fait la une : une phrase criée après le match est devenue le centre d’un débat sur la fierté, la rivalité et l’interprétation des mots.\\n\\n## Un match qui bascule après la pause\\n\\nHaïti a ouvert le score dès la 9e minute grâce à Don Deedson Louicius. Selon Le Nouvelliste, Isidor a manqué un penalty à la 21e minute. En seconde période, il a rebondi : il a marqué à la 51e minute, puis porté le score à 3-1 à la 67e. Dorny Romero avait inscrit le but dominicain entre les deux réalisations. Yassin Fortuné a scellé le score pour Haïti à la 77e minute.\\n\\nIl s’agissait du premier doublé d’Isidor avec la sélection haïtienne, rapporte le journal. Ce résultat a compté dans le parcours du groupe et a contribué à la qualification d’Haïti pour les quarts de finale de la Ligue des nations.\\n\\n## La phrase après le coup de sifflet\\n\\nAprès la rencontre, Isidor a crié : « L’Hispaniola c’est Haïti ! This is Haiti! » La phrase s’est rapidement propagée. Hispaniola est l’île que se partagent Haïti et la République dominicaine. Les mots pouvaient donc être entendus comme une affirmation identitaire, mais beaucoup les ont interprétés comme une provocation territoriale.\\n\\nLa Fédération haïtienne de football a défendu cette célébration comme une expression de l’attachement d’Isidor à ses racines haïtiennes. Elle a affirmé qu’elle ne devait pas être interprétée comme de l’hostilité ou un manque de respect envers un autre peuple. C’est la position de la fédération. La phrase ne modifie pas la réalité géographique : l’île est partagée entre deux pays.\\n\\n## Les réactions et ce que l’on sait\\n\\nAssociated Press rapporte que la fédération dominicaine a déposé une plainte auprès de la Concacaf et que l’organisation a ouvert une procédure disciplinaire. Toutefois, selon le même reportage, le ministre dominicain des Sports n’a pas cité Isidor lorsqu’il a annoncé que l’équipe haïtienne ne pourrait plus jouer dans les stades du pays. Il a plutôt évoqué des dégâts que des supporters auraient causés au stade. Le reportage d’AP du 5 octobre ne fait état d’aucune décision finale sur la procédure.\\n\\nUn grand moment de football est ainsi devenu un débat qui mérite mieux qu’une réaction immédiate en ligne. Isidor a inscrit deux buts dans une victoire importante pour Haïti. La FHF a présenté son cri comme une célébration. La controverse montre comment une rivalité entre voisins peut donner une portée politique à une phrase, surtout lorsque l’histoire et les relations entre les deux pays sont déjà chargées.","image_credit":"Timmy96 / Wikimedia Commons — CC0 1.0 (photo non modifiée)"}','1','2026-10-10T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM articles WHERE id='geovyora-wilson-isidor-2026' AND updated_at='2026-10-10T00:00:00+00:00') ON CONFLICT(target_type,target_id,version,locale) DO NOTHING;
INSERT INTO translations(id,target_type,target_id,version,locale,data,manual,created_at) SELECT 'geovyora-wilson-isidor-2026-en','article','geovyora-wilson-isidor-2026','2026-10-10T00:00:00+00:00','en','{"title":"Wilson Isidor: a Haiti brace, then a phrase that sparked debate","subtitle":"After Haiti’s 4–1 win in Santo Domingo, the striker celebrated with words that quickly became a regional controversy.","body":"On October 1, Haiti beat the Dominican Republic 4–1 in Santo Domingo in the Concacaf Nations League. Wilson Isidor scored twice. His performance was not the only reason his name became a major story: a phrase he shouted after the match turned into a debate about pride, rivalry and how words are interpreted.\\n\\n## A match that opened up after halftime\\n\\nHaiti took the lead in the ninth minute through Don Deedson Louicius. Le Nouvelliste reports that Isidor missed a penalty in the 21st minute. He recovered in the second half, scoring in the 51st minute and making it 3–1 in the 67th. Dorny Romero scored for the Dominican side between those goals. Yassin Fortuné added Haiti’s final goal in the 77th minute.\\n\\nIt was Isidor’s first brace for Haiti’s national team, the newspaper reported. The result mattered in the group campaign and helped Haiti secure a place in the Nations League quarterfinals.\\n\\n## The words after the final whistle\\n\\nAfter the match, Isidor shouted: “L’Hispaniola c’est Haiti! This is Haiti!” The phrase spread quickly. Hispaniola is the island shared by Haiti and the Dominican Republic. The words could be heard as an expression of identity, but many people interpreted them as a territorial provocation.\\n\\nThe Haitian Football Federation defended the celebration as an expression of Isidor’s attachment to his Haitian roots. It said the remark should not be treated as hostility or disrespect toward another people. That is the federation’s position. The shout does not change the geographic fact: the island is shared by two countries.\\n\\n## The reaction and what is known\\n\\nThe Associated Press reports that the Dominican Football Federation filed a complaint with Concacaf and that the confederation opened a disciplinary case. However, AP’s report also says the Dominican sports minister did not mention Isidor when announcing that Haiti’s team would no longer be allowed to play in the country’s stadiums. He instead cited damage that Haitian fans allegedly caused at the stadium. AP’s October 5 report did not give a final decision in the case.\\n\\nA major football moment has therefore become a discussion that deserves more than a quick reaction online. Isidor scored twice in a win with real sporting weight for Haiti. The FHF framed his shout as celebration. The debate that followed shows how a rivalry between neighbors can give political weight to a phrase, especially when the countries’ history and relationship are already fraught.","image_credit":"Timmy96 / Wikimedia Commons — CC0 1.0 (photo unmodified)"}','1','2026-10-10T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM articles WHERE id='geovyora-wilson-isidor-2026' AND updated_at='2026-10-10T00:00:00+00:00') ON CONFLICT(target_type,target_id,version,locale) DO NOTHING;
INSERT INTO translations(id,target_type,target_id,version,locale,data,manual,created_at) SELECT 'geovyora-wilson-isidor-2026-pt_BR','article','geovyora-wilson-isidor-2026','2026-10-10T00:00:00+00:00','pt-BR','{"title":"Wilson Isidor: dois gols pelo Haiti e uma frase que gerou debate","subtitle":"Depois da vitória por 4 a 1 em Santo Domingo, o atacante celebrou com palavras que rapidamente viraram polêmica regional.","body":"Em 1º de outubro, o Haiti venceu a República Dominicana por 4 a 1 em Santo Domingo, pela Liga das Nações da Concacaf. Wilson Isidor marcou dois gols. Mas a atuação não foi o único motivo para seu nome ganhar destaque: uma frase gritada depois da partida se tornou o centro de um debate sobre orgulho, rivalidade e interpretação.\\n\\n## Um jogo que mudou no segundo tempo\\n\\nO Haiti abriu o placar aos nove minutos, com Don Deedson Louicius. Segundo o Le Nouvelliste, Isidor perdeu um pênalti aos 21 minutos. No segundo tempo, reagiu: marcou aos 51 e fez 3 a 1 aos 67. Dorny Romero marcou para os dominicanos entre os dois gols. Yassin Fortuné fechou o placar para o Haiti aos 77 minutos.\\n\\nFoi o primeiro jogo de dois gols de Isidor pela seleção haitiana, informou o jornal. O resultado foi importante na campanha do grupo e ajudou o Haiti a garantir vaga nas quartas de final da Liga das Nações.\\n\\n## A frase depois do apito final\\n\\nDepois da partida, Isidor gritou: “L’Hispaniola c’est Haiti! This is Haiti!” A frase se espalhou rapidamente. Hispaniola é a ilha compartilhada pelo Haiti e pela República Dominicana. Por isso, as palavras podiam ser entendidas como uma afirmação de identidade, mas muitas pessoas as interpretaram como provocação territorial.\\n\\nA Federação Haitiana de Futebol defendeu a comemoração como expressão do vínculo de Isidor com suas raízes haitianas. A entidade afirmou que a fala não deveria ser interpretada como hostilidade ou desrespeito a outro povo. Essa é a posição da federação. O grito não altera o fato geográfico: a ilha é compartilhada por dois países.\\n\\n## Reações e o que se sabe\\n\\nA Associated Press informa que a federação dominicana apresentou uma queixa à Concacaf e que a confederação abriu um procedimento disciplinar. Porém, a reportagem da AP também diz que o ministro dominicano dos Esportes não mencionou Isidor ao anunciar que a seleção haitiana não poderia mais jogar nos estádios do país. Ele citou danos que torcedores haitianos teriam causado ao estádio. A reportagem da AP de 5 de outubro não informava uma decisão final sobre o caso.\\n\\nAssim, um grande momento do futebol se transformou em um debate que merece mais do que uma reação imediata nas redes. Isidor marcou duas vezes em uma vitória importante para o Haiti. A federação haitiana apresentou o grito como comemoração. A controvérsia mostra como a rivalidade entre vizinhos pode dar peso político a uma frase, sobretudo quando a história e a relação entre os dois países já são delicadas.","image_credit":"Timmy96 / Wikimedia Commons — CC0 1.0 (foto sem alterações)"}','1','2026-10-10T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM articles WHERE id='geovyora-wilson-isidor-2026' AND updated_at='2026-10-10T00:00:00+00:00') ON CONFLICT(target_type,target_id,version,locale) DO NOTHING;
INSERT INTO translations(id,target_type,target_id,version,locale,data,manual,created_at) SELECT 'geovyora-wilson-isidor-2026-es','article','geovyora-wilson-isidor-2026','2026-10-10T00:00:00+00:00','es','{"title":"Wilson Isidor: doblete con Haití y una frase que desató el debate","subtitle":"Tras la victoria haitiana por 4-1 en Santo Domingo, el delantero celebró con unas palabras que pronto se convirtieron en polémica regional.","body":"El 1 de octubre, Haití venció a República Dominicana por 4-1 en Santo Domingo, en la Liga de Naciones de Concacaf. Wilson Isidor marcó dos goles. Pero su actuación no fue la única razón por la que su nombre se convirtió en noticia: una frase que gritó después del partido pasó a ser el centro de un debate sobre orgullo, rivalidad e interpretación.\\n\\n## Un partido que cambió tras el descanso\\n\\nHaití se adelantó en el minuto nueve con un gol de Don Deedson Louicius. Según Le Nouvelliste, Isidor falló un penalti en el minuto 21. En la segunda parte reaccionó: marcó en el 51 y puso el 3-1 en el 67. Dorny Romero anotó para el equipo dominicano entre esos dos goles. Yassin Fortuné cerró el marcador para Haití en el minuto 77.\\n\\nFue el primer doblete de Isidor con la selección haitiana, informó el periódico. El resultado tuvo peso en la fase de grupos y ayudó a Haití a conseguir un lugar en los cuartos de final de la Liga de Naciones.\\n\\n## Las palabras tras el pitido final\\n\\nDespués del partido, Isidor gritó: «L’Hispaniola c’est Haiti! This is Haiti!». La frase se difundió rápidamente. La Española es la isla que comparten Haití y República Dominicana. Por eso, las palabras podían escucharse como una expresión de identidad, pero muchas personas las interpretaron como una provocación territorial.\\n\\nLa Federación Haitiana de Fútbol defendió la celebración como una expresión del vínculo de Isidor con sus raíces haitianas. Afirmó que el comentario no debía considerarse hostilidad ni falta de respeto hacia otro pueblo. Esa es la postura de la federación. El grito no cambia la realidad geográfica: la isla está compartida por dos países.\\n\\n## Las reacciones y lo que se sabe\\n\\nAssociated Press informa de que la federación dominicana presentó una queja ante Concacaf y que la confederación abrió un procedimiento disciplinario. Sin embargo, el mismo reportaje señala que el ministro dominicano de Deportes no mencionó a Isidor al anunciar que Haití ya no podría jugar en los estadios del país. En cambio, habló de daños que, según él, causaron aficionados haitianos en el estadio. El informe de AP del 5 de octubre no daba una decisión final sobre el caso.\\n\\nAsí, un gran momento futbolístico se convirtió en un debate que merece más que una reacción apresurada en internet. Isidor marcó dos goles en una victoria importante para Haití. La federación haitiana describió el grito como una celebración. La controversia muestra cómo la rivalidad entre vecinos puede dar peso político a una frase, especialmente cuando la historia y la relación entre ambos países ya son complejas.","image_credit":"Timmy96 / Wikimedia Commons — CC0 1.0 (foto sin modificar)"}','1','2026-10-10T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM articles WHERE id='geovyora-wilson-isidor-2026' AND updated_at='2026-10-10T00:00:00+00:00') ON CONFLICT(target_type,target_id,version,locale) DO NOTHING;
INSERT INTO articles(id,slug,title,subtitle,body,category,region,kind,image,image_credit,author,locale,status,featured,demo,sponsored,publish_at,created_at,updated_at,sources,tags) VALUES ('geovyora-khaby-lame-ai-twin-2026','khaby-lame-jimo-dijital-ako-975-milyon','Khaby Lame ak pwojè jimo dijital la: kisa akò $975 milyon an di vre?','Dosye a pale de aksyon konpayi ak dwa pou devlope yon imaj dijital li, valè anonse a pa menm ak yon peman lajan kach.','Khaby Lame vin popilè ak videyo kout kote li reyaji an silans devan “solisyon” ki konplike twòp. Koulye a, atansyon an deplase sou yon lòt kesyon: ki limit ki genyen lè yon mak vle fè prezans yon kreyatè kontinye atravè yon vèsyon dijital li?

## Sa dosye SEC a di sou $975 milyon an

Nan yon dokiman li te depoze 9 janvye 2026, Rich Sparkle Holdings te di li te siyen yon akò pou achte tout aksyon Step Distinctive Limited, konpayi ki lye ak biznis ak mak Lame a. Pri ki make nan akò a se $975 milyon, men peman an te dwe fèt ak 75 milyon aksyon Rich Sparkle, pa avèk $975 milyon lajan kach. Kontra a te gen kondisyon: yon evalyasyon konpayi an ki satisfè Rich Sparkle, verifikasyon finansye ak legal, epi apwobasyon pou aksyon yo ka negosye sou mache a.

Nan yon kominike 11 janvye, Rich Sparkle te deklare akizisyon an te fini. Sa se sa konpayi an te anonse. Men dokiman SEC a te dekri tranzaksyon an kòm yon akò ki depann de kondisyon sa yo. Se poutèt sa li pi egzak pou pale de yon kontra ki te gen yon valè anonse, olye pou di Lame te resevwa $975 milyon.

## Pwojè “jimo dijital” la

Menm anons konpayi an pale de itilizasyon modèl figi, vwa ak konpòtman Lame pou konstwi yon jimo dijital ak entèlijans atifisyèl. Dapre plan an, vèsyon sa a ta ka pèmèt kontni nan plizyè lang ak prezans nan komès an dirèk san kreyatè a bezwen la an pèsòn chak fwa. Komisyon Ewopeyen an, nan yon atik sou dwa pwopriyete entelektyèl, dekri otorizasyon sa yo kòm yon pati nan aranjman an.

Sa se yon pwojè komèsyal, pa prèv ke jimo dijital la deja ap fonksyone oswa ke li deja pwodui revni. Nan dokiman nou site yo, plan an ak rezilta posib yo dwe rete separe.

## Sa dokiman finansye ki pi resan yo ajoute

Nan rapò finansye li te pibliye 30 septanm 2026 pou sis mwa ki te fini 31 mas, Rich Sparkle dekri operasyon li kòm sèvis enprime finansye ak sèvis antrepriz nan Hong Kong, epi li di tout revni peryòd la te soti nan kliyan Hong Kong. Rapò sa a pa pale de Step Distinctive oswa de jimo dijital la. Sa pa pwouve tranzaksyon an pa fèt, men, lè nou mete l bò kote anons janvye a, dosye piblik nou jwenn yo pa bay yon foto konplè sou fason biznis la te entegre.

Pou piblik la, pwen ki merite suiv la se pa sèlman valè ki nan tit la. Se fason itilizasyon imaj, vwa ak jès yon kreyatè ap parèt klèman kòm kontni dijital, ki konpayi ki gen dwa komèsyal yo, epi si pwojeksyon lavant yo vin tounen rezilta reyèl. Jiska gen prèv sou sa, “jimo dijital” la rete yon plan ki gen gwo potansyèl, pa yon reyalite komèsyal ki deja demontre.','Teknoloji','international','article','/static/articles/khaby-lame-2025.jpg','Sam Barnes / Web Summit via Sportsfile — CC BY 4.0 (foto a pa modifye)','Geovyora','ht','published','0','0','0','2026-10-10T00:00:00+00:00','2026-10-10T00:00:00+00:00','2026-10-10T00:00:00+00:00','https://www.sec.gov/Archives/edgar/data/2031688/000121390026002713/ea0272099-6k_rich.htm
https://www.prnewswire.com/news-releases/rich-sparkle-holdings-closes-acquisition-of-tiktok-icon-khaby-lames-core-company-302658017.html
https://www.sec.gov/Archives/edgar/data/2031688/000121390026104911/ea030682201ex99-1.htm
https://www.sec.gov/Archives/edgar/data/2031688/000121390026104911/ea030682201ex99-2.htm
https://intellectual-property-helpdesk.ec.europa.eu/news-events/news/khaby-lame-sells-his-image-rights-create-ai-powered-digital-twins-britney-spears-sells-rights-her-2026-02-12_en
https://commons.wikimedia.org/wiki/File:Khaby_Lame,_Nov_2025.jpg
https://creativecommons.org/licenses/by/4.0/','Khaby Lame,AI,entèlektyèl atifisyèl,kreyatè dijital,jimo dijital') ON CONFLICT(slug) DO NOTHING;
INSERT INTO translations(id,target_type,target_id,version,locale,data,manual,created_at) SELECT 'geovyora-khaby-lame-ai-twin-2026-fr','article','geovyora-khaby-lame-ai-twin-2026','2026-10-10T00:00:00+00:00','fr','{"title":"Khaby Lame et son double numérique : que dit vraiment l’accord de 975 millions de dollars ?","subtitle":"Le dossier parle d’actions et de droits de développement d’une version numérique , la valeur annoncée n’est pas un paiement en espèces.","body":"Khaby Lame s’est fait connaître avec de courtes vidéos où il réagit sans parler aux « solutions » inutilement compliquées. L’attention se porte désormais sur une autre question : quelles limites faut-il poser lorsqu’une marque veut prolonger la présence d’un créateur grâce à une version numérique de lui-même ?\\n\\n## Ce que le dossier de la SEC dit sur les 975 millions\\n\\nDans un document déposé le 9 janvier 2026, Rich Sparkle Holdings a indiqué avoir signé un accord pour acquérir toutes les actions de Step Distinctive Limited, une société liée aux activités et à la marque de Lame. La contrepartie prévue était de 975 millions de dollars, mais elle devait être versée en 75 millions d’actions Rich Sparkle, et non en 975 millions de dollars en espèces. L’opération restait soumise à des conditions : une valorisation jugée satisfaisante par Rich Sparkle, des vérifications financières et juridiques, ainsi que l’autorisation de négocier les actions sur le marché.\\n\\nDans un communiqué du 11 janvier, Rich Sparkle a déclaré que l’acquisition était terminée. C’est l’annonce de l’entreprise. Le document déposé auprès de la SEC, lui, décrivait une transaction soumise à ces conditions. Il est donc plus exact de parler d’un accord affichant une valeur de 975 millions, plutôt que d’affirmer que Lame a reçu cette somme en espèces.\\n\\n## Le projet de « double numérique »\\n\\nLe communiqué de l’entreprise évoque aussi l’utilisation de modèles du visage, de la voix et du comportement de Lame pour créer un double numérique par intelligence artificielle. Selon le projet, cette version pourrait produire du contenu multilingue et intervenir dans le commerce en direct sans que le créateur soit présent à chaque fois. La Commission européenne, dans un article consacré à la propriété intellectuelle, décrit ces autorisations comme faisant partie de l’accord.\\n\\nIl s’agit d’un projet commercial, pas d’une preuve que le double numérique fonctionne déjà ou génère des revenus. Dans les documents cités ici, il faut distinguer le projet des résultats éventuels.\\n\\n## Ce qu’ajoutent les dernières données financières\\n\\nDans ses résultats publiés le 30 septembre 2026 pour le semestre clos le 31 mars, Rich Sparkle décrit ses activités comme des services d’impression financière et des services aux entreprises à Hong Kong. La société indique que l’ensemble des revenus de la période provenait de clients hongkongais. Le rapport ne mentionne ni Step Distinctive ni le double numérique. Cela ne prouve pas que l’opération n’a pas eu lieu , toutefois, mis en regard de l’annonce de janvier, les documents publics consultés ne donnent pas une image complète de l’intégration de cette activité.\\n\\nPour le public, la question à suivre ne se limite pas au chiffre du titre. Il faudra voir comment l’usage du visage, de la voix et des gestes d’un créateur est présenté clairement comme du contenu numérique, quelles entreprises disposent de droits commerciaux et si les projections de ventes deviennent des résultats réels. Tant que ces éléments ne sont pas démontrés, le « double numérique » reste un projet à fort potentiel, et non un succès commercial déjà établi.","image_credit":"Sam Barnes / Web Summit via Sportsfile — CC BY 4.0 (photo non modifiée)"}','1','2026-10-10T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM articles WHERE id='geovyora-khaby-lame-ai-twin-2026' AND updated_at='2026-10-10T00:00:00+00:00') ON CONFLICT(target_type,target_id,version,locale) DO NOTHING;
INSERT INTO translations(id,target_type,target_id,version,locale,data,manual,created_at) SELECT 'geovyora-khaby-lame-ai-twin-2026-en','article','geovyora-khaby-lame-ai-twin-2026','2026-10-10T00:00:00+00:00','en','{"title":"Khaby Lame and the digital twin plan: what does the $975 million agreement actually say?","subtitle":"The deal describes company shares and rights to develop a digital likeness, its announced value is not a cash payment.","body":"Khaby Lame became famous for short videos in which he silently reacts to unnecessarily complicated “solutions.” Attention has now shifted to a different question: what limits apply when a brand wants to extend a creator’s presence through a digital version of him?\\n\\n## What the SEC filing says about $975 million\\n\\nIn a filing dated January 9, 2026, Rich Sparkle Holdings said it had signed an agreement to acquire all shares of Step Distinctive Limited, a company linked to Lame’s business and brand. The stated consideration was $975 million, but it was to be paid through 75 million Rich Sparkle shares, not $975 million in cash. The agreement was conditional on several steps: a valuation acceptable to Rich Sparkle, due diligence, and approval for the shares to be traded on the stock exchange.\\n\\nIn a January 11 press release, Rich Sparkle said the acquisition had been completed. That is the company’s announcement. The SEC filing, however, described a transaction subject to those conditions. It is therefore more precise to call this an agreement with a stated $975 million value than to say Lame received $975 million in cash.\\n\\n## The “digital twin” plan\\n\\nThe company’s announcement also described using models of Lame’s face, voice and behavior to build an AI digital twin. Under the plan, that version could support multilingual content and livestream commerce without requiring the creator to be physically present every time. The European Commission’s Intellectual Property Helpdesk describes those authorizations as part of the arrangement.\\n\\nThis is a commercial plan, not proof that the digital twin is already operating or earning revenue. In the documents cited here, the plan and any eventual results should be kept separate.\\n\\n## What the latest financial documents add\\n\\nIn results released on September 30, 2026, for the six months ended March 31, Rich Sparkle describes its operations as financial-printing and corporate services in Hong Kong. The company says all revenue for the period came from Hong Kong clients. The report does not mention Step Distinctive or the digital twin. That does not prove the transaction did not happen, but alongside the January announcement, the public documents reviewed do not provide a complete picture of how the business was integrated.\\n\\nFor audiences, the question to follow is not just the headline figure. It is whether the use of a creator’s face, voice and gestures is clearly disclosed as digital content, which companies hold commercial rights, and whether sales projections become real results. Until those results are demonstrated, the “digital twin” remains a high-potential plan, not an established commercial success.","image_credit":"Sam Barnes / Web Summit via Sportsfile — CC BY 4.0 (photo unmodified)"}','1','2026-10-10T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM articles WHERE id='geovyora-khaby-lame-ai-twin-2026' AND updated_at='2026-10-10T00:00:00+00:00') ON CONFLICT(target_type,target_id,version,locale) DO NOTHING;
INSERT INTO translations(id,target_type,target_id,version,locale,data,manual,created_at) SELECT 'geovyora-khaby-lame-ai-twin-2026-pt_BR','article','geovyora-khaby-lame-ai-twin-2026','2026-10-10T00:00:00+00:00','pt-BR','{"title":"Khaby Lame e o plano do gêmeo digital: o que diz, de fato, o acordo de US$ 975 milhões?","subtitle":"O acordo prevê ações da empresa e direitos para desenvolver uma versão digital, o valor anunciado não é um pagamento em dinheiro.","body":"Khaby Lame ficou conhecido por vídeos curtos em que reage em silêncio a “soluções” desnecessariamente complicadas. Agora, a atenção se volta para outra pergunta: quais são os limites quando uma marca quer prolongar a presença de um criador por meio de uma versão digital dele?\\n\\n## O que o documento da SEC diz sobre os US$ 975 milhões\\n\\nEm um documento apresentado em 9 de janeiro de 2026, a Rich Sparkle Holdings informou ter assinado um acordo para comprar todas as ações da Step Distinctive Limited, empresa ligada aos negócios e à marca de Lame. O valor indicado foi de US$ 975 milhões, mas o pagamento seria feito com 75 milhões de ações da Rich Sparkle, e não com US$ 975 milhões em dinheiro. O acordo dependia de algumas condições: uma avaliação considerada satisfatória pela Rich Sparkle, auditoria prévia e aprovação para negociação das ações na bolsa.\\n\\nEm um comunicado de 11 de janeiro, a Rich Sparkle afirmou que a aquisição havia sido concluída. Essa é a declaração da empresa. O documento enviado à SEC, porém, descrevia uma transação sujeita àquelas condições. Por isso, é mais preciso falar em um acordo com valor anunciado de US$ 975 milhões do que afirmar que Lame recebeu essa quantia em dinheiro.\\n\\n## O plano do “gêmeo digital”\\n\\nO comunicado da empresa também descreveu o uso de modelos do rosto, da voz e do comportamento de Lame para criar um gêmeo digital com inteligência artificial. Pelo plano, essa versão poderia ajudar a produzir conteúdo em vários idiomas e participar de comércio por transmissões ao vivo sem exigir a presença física do criador em todas as ocasiões. O Intellectual Property Helpdesk da Comissão Europeia descreve essas autorizações como parte do acordo.\\n\\nTrata-se de um plano comercial, não de uma prova de que o gêmeo digital já esteja em operação ou gerando receita. Nos documentos citados, o projeto e os resultados futuros devem ser tratados separadamente.\\n\\n## O que os documentos financeiros mais recentes acrescentam\\n\\nNos resultados divulgados em 30 de setembro de 2026, referentes aos seis meses encerrados em 31 de março, a Rich Sparkle descreve suas operações como serviços de impressão financeira e serviços corporativos em Hong Kong. A empresa afirma que toda a receita do período veio de clientes de Hong Kong. O relatório não menciona a Step Distinctive nem o gêmeo digital. Isso não prova que a operação não aconteceu, porém, junto ao anúncio de janeiro, os documentos públicos consultados não esclarecem por completo como o negócio foi integrado.\\n\\nPara o público, o ponto a acompanhar não é apenas o número da manchete. É preciso observar se o uso do rosto, da voz e dos gestos de um criador será identificado claramente como conteúdo digital, quais empresas terão direitos comerciais e se as projeções de vendas se transformarão em resultados reais. Até que isso seja demonstrado, o “gêmeo digital” continua sendo um plano de grande potencial, não um sucesso comercial já comprovado.","image_credit":"Sam Barnes / Web Summit via Sportsfile — CC BY 4.0 (foto sem alterações)"}','1','2026-10-10T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM articles WHERE id='geovyora-khaby-lame-ai-twin-2026' AND updated_at='2026-10-10T00:00:00+00:00') ON CONFLICT(target_type,target_id,version,locale) DO NOTHING;
INSERT INTO translations(id,target_type,target_id,version,locale,data,manual,created_at) SELECT 'geovyora-khaby-lame-ai-twin-2026-es','article','geovyora-khaby-lame-ai-twin-2026','2026-10-10T00:00:00+00:00','es','{"title":"Khaby Lame y el plan del gemelo digital: ¿qué dice realmente el acuerdo de 975 millones de dólares?","subtitle":"El acuerdo habla de acciones de la empresa y derechos para desarrollar una versión digital, el valor anunciado no es un pago en efectivo.","body":"Khaby Lame se hizo famoso con vídeos breves en los que reacciona sin hablar ante “soluciones” innecesariamente complicadas. Ahora la atención se centra en otra pregunta: ¿qué límites existen cuando una marca quiere prolongar la presencia de un creador mediante una versión digital suya?\\n\\n## Qué dice el documento de la SEC sobre los 975 millones\\n\\nEn una presentación del 9 de enero de 2026, Rich Sparkle Holdings dijo que había firmado un acuerdo para comprar todas las acciones de Step Distinctive Limited, una empresa vinculada a los negocios y la marca de Lame. La contraprestación indicada era de 975 millones de dólares, pero se pagaría mediante 75 millones de acciones de Rich Sparkle, no con 975 millones de dólares en efectivo. La operación estaba sujeta a varias condiciones: una valoración aceptable para Rich Sparkle, una revisión de diligencia debida y la aprobación para negociar las acciones en bolsa.\\n\\nEn un comunicado del 11 de enero, Rich Sparkle afirmó que la adquisición se había completado. Esa fue la declaración de la empresa. Sin embargo, el documento presentado ante la SEC describía una operación sujeta a esas condiciones. Por eso es más preciso hablar de un acuerdo con un valor anunciado de 975 millones que afirmar que Lame recibió esa cantidad en efectivo.\\n\\n## El plan del «gemelo digital»\\n\\nEl comunicado de la empresa también describió el uso de modelos del rostro, la voz y el comportamiento de Lame para crear un gemelo digital mediante inteligencia artificial. Según el plan, esa versión podría facilitar contenidos en varios idiomas y comercio en directo sin que el creador tenga que estar físicamente presente en cada ocasión. El Intellectual Property Helpdesk de la Comisión Europea describe esas autorizaciones como parte del acuerdo.\\n\\nSe trata de un plan comercial, no de una prueba de que el gemelo digital ya esté funcionando o genere ingresos. En los documentos citados, el plan debe distinguirse de cualquier resultado futuro.\\n\\n## Qué añaden los documentos financieros más recientes\\n\\nEn los resultados publicados el 30 de septiembre de 2026 para los seis meses terminados el 31 de marzo, Rich Sparkle describe sus operaciones como servicios de impresión financiera y servicios corporativos en Hong Kong. La empresa señala que todos los ingresos del periodo procedieron de clientes de Hong Kong. El informe no menciona Step Distinctive ni el gemelo digital. Eso no demuestra que la operación no se realizara, pero, junto al anuncio de enero, los documentos públicos consultados no ofrecen una imagen completa de cómo se integró el negocio.\\n\\nPara el público, la cuestión que conviene seguir no es solo la cifra del titular. También importa si el uso del rostro, la voz y los gestos de un creador se identifica claramente como contenido digital, qué empresas tienen derechos comerciales y si las proyecciones de ventas se convierten en resultados reales. Hasta que se demuestre, el «gemelo digital» sigue siendo un plan con gran potencial, no un éxito comercial ya comprobado.","image_credit":"Sam Barnes / Web Summit via Sportsfile — CC BY 4.0 (foto sin modificar)"}','1','2026-10-10T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM articles WHERE id='geovyora-khaby-lame-ai-twin-2026' AND updated_at='2026-10-10T00:00:00+00:00') ON CONFLICT(target_type,target_id,version,locale) DO NOTHING;
